 for k in range(n):
  p=next((j for j in range(k,n) if M[j][k]),None);assert p is not None,'singular contact minor'
  M[k],M[p]=M[p],M[k];d=M[k][k];M[k]=[x/d for x in M[k]]
  for j in range(n):
   if j!=k:
    d=M[j][k];M[j]=[x-d*y for x,y in zip(M[j],M[k])]
